INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Fully decentralised — no clearance', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. Format specifications, ZRE/OZG-RE technical requirements, and enforcement posture continue to evolve as the 2027 and 2028 phases approach — confirm current requirements directly with the BMF or your ERP/e-invoicing provider before building an integration.', 'Germany''s reform is unusually gradual by design — a pure receiving mandate first, then issuance phased in strictly by company turnover, with no domestic reporting obligation attached (yet).', 'Germany accepts two genuinely different national formats side by side, plus Peppol BIS as a third option — there''s real choice here, unlike most CTC countries.', 'This is the biggest structural difference from France, Italy, or Poland: Germany has no clearance authority and no mandated channel for B2B at all.', 'Unlike Romania, France, or Belgium, there''s no directory to join or account to open for B2B — Germany''s decentralised model means "registration" is really about internal readiness and, where relevant, your specific government customer''s portal.', 'Germany has no dedicated e-invoicing fine — non-compliance is folded into existing VAT and bookkeeping law, and the sharpest risk isn''t a government fine at all.' FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '2 formats', 'XRechnung / ZUGFeRD');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'No CTC', 'No central platform (B2B)');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '8 yrs', 'Archive requirement');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '€5,000', 'Max fine per offence');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '2028', 'Full B2B issuance mandate');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'XRechnung', '[["Type", "Pure XML \u2014 no visual layer"], ["Syntax", "UBL 2.1 or UN/CEFACT CII"], ["Current version", "XRechnung 3.0.2 (moving to 4.0)"], ["Mandatory for", "All B2G invoices; increasingly used for B2B"]]', 'Because XRechnung has no human-readable rendering built in, recipients need software that can actually display or process the XML — this is part of why ZUGFeRD is often preferred for B2B.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'ZUGFeRD', '[["Type", "Hybrid \u2014 PDF/A-3 + embedded XML"], ["Current version", "ZUGFeRD 2.3.x (2.1+ required)"], ["Cross-compatible with", "Factur-X (France) since v2.1"], ["Preferred for", "B2B \u2014 readable without specialist software"]]', 'The embedded XML follows the same CII syntax family as XRechnung''s CII option — so a well-built pipeline can often generate both formats from the same underlying data model.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Mandatory content (§14 UStG)', '[["Party data", "Name, address, VAT ID for supplier & customer"], ["Transaction detail", "Description, quantity, unit price, date of supply"], ["Tax detail", "Net amount, VAT rate, VAT amount, gross total, reverse-charge/exemption flags"], ["Digital signature", "Not required"]]', 'All of this must live in the structured data itself — attaching a compliant-looking PDF alongside a non-compliant XML doesn''t satisfy the mandate. "XML" alone isn''t a compliance indicator either; it must be a recognised EN 16931 implementation.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'German CIUS quirks', '[["BT-72 (actual delivery date)", "Optional in EN 16931 \u2192 mandatory in German CIUS"], ["B2G payment means codes", "Restricted list (e.g. 30 = transfer, 58 = SEPA)"], ["Archiving", "8 years, GoBD-compliant, original structured format"]]', 'Saving only a printed copy of a ZUGFeRD invoice instead of the original file violates GoBD record-keeping rules — the embedded XML is the part that must survive, not just the PDF rendering.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'B2B: fully decentralised', '[["Clearance authority", "None"], ["Mandated channel", "None \u2014 any agreed method"], ["Accepted channels", "Email, portal/download link, EDI, FTP/FTPS, web services, Peppol"]]', 'The mandate governs the format of the invoice, not how it travels. Two trading partners are free to agree on whatever transmission method suits them, as long as the file itself is a compliant structured invoice.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'B2G: two federal portals', '[["ZRE", "Direct federal administration (ministries + directly subordinate bodies)"], ["OZG-RE", "Indirect federal administration + several federal states"], ["Routing identifier", "Leitweg-ID (format XX-XXXXXXXXXX-XX)"]]', 'Your contracting authority tells you which platform and Leitweg-ID to use — check your contract or procurement terms if unsure. Authorities must also offer Peppol as a transmission option where automated exchange is possible.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Common B2G rejection causes', '[["Missing/wrong Leitweg-ID", "Must appear in BT-10 (BuyerReference)"], ["Invalid VAT breakdown", "Each VAT category needs a separate breakdown"], ["Attachment size", "ZRE caps embedded attachments at 5 MB"], ["Profile mismatch", "Using XRechnung 2.x where 3.x is required"]]', 'If your invoice bounces from ZRE or OZG-RE, these four causes cover the large majority of real-world rejections — check the Leitweg-ID and profile version first.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 3 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Audit access', '[["Z1 / Z2 access", "Direct read-only access to your accounting system"], ["Z3 access", "Structured data export of e-invoice records"], ["Submission channel", "ELSTER (where applicable)"]]', 'German tax authorities can request any of these three access modes during an audit — keeping invoices systematically archived in a standard, exportable format materially reduces audit friction.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '💸 The real risk is your buyer''s VAT deduction', NULL, NULL, 'A non-compliant invoice is treated as not properly issued — your customer can''t deduct input VAT until you reissue a valid one. In practice, this commercial pressure from buyers is a stronger compliance driver than the statutory fine itself.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🕊️ No penalties during 2025–2026 transition', NULL, NULL, 'While paper and PDF invoices remain permitted by mutual agreement during the transition period, no fines apply for using them — enforcement is expected to ramp up once each business''s mandatory phase actually begins.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📁 GoBD archiving risk', NULL, NULL, 'Failing to preserve the original structured file (e.g. keeping only a printed copy) can trigger fines or, in serious cases, allow tax authorities to estimate your tax base rather than rely on your records.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Work out which phase applies to you', 'Check your prior-year turnover against the €800,000 threshold to know whether your issuing obligation starts in 2027 or 2028 — and confirm whether Kleinunternehmer status (§19 UStG) exempts you from issuing altogether.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Choose your format: XRechnung, ZUGFeRD, or Peppol BIS', 'XRechnung suits high-volume automated B2B flows; ZUGFeRD suits relationships where a human still needs to open and read the invoice; Peppol BIS suits businesses already active on that network for other European trade.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm §14 UStG data lives in the structured file itself', 'Validate that supplier/customer details, transaction detail, and full tax breakdown are embedded in the XML — not just present in an accompanying human-readable PDF.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'For B2G: create your ZRE or OZG-RE account', 'Register on whichever platform your public-sector customer directs you to, and confirm the correct Leitweg-ID for that specific contracting authority before your first submission.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Agree a transmission channel with each B2B partner', 'Since there''s no mandated channel, settle this explicitly with your trading partners — email, a shared portal, EDI, or Peppol are all valid as long as the underlying file is compliant.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Set up GoBD-compliant archiving', 'Store the original structured file (not a printed copy) for the required retention period, and confirm you can produce Z1/Z2/Z3-style audit access if the tax office asks.');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108886/eInvoicing+in+Germany', 0 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'EU Digital Building Blocks — Germany');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Failure to issue a required e-invoice', '§26a UStG (administrative offence)', '€5,000 per offence');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Specific record-retention violations', '§26a UStG', '€1,000');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Germany';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'More serious cases under §26a(1)', '§26a UStG', 'Up to €30,000');
